var smallestUniqueSubarray = function(nums) {
    const n = nums.length;
    let largest = 0;

    for (const num of nums) {
        largest = Math.max(largest, num);
    }

    const BASE = largest + 1;
    const MOD = 1000000007;

    function hasUnique(length) {
        // The first value in a window has weight BASE^(length - 1).
        let highestPower = 1;
        for (let i = 1; i < length; i++) {
            highestPower = (highestPower * BASE) % MOD;
        }

        const groupsByHash = new Map();
        let hash = 0;

        function sameWindow(firstStart, secondStart) {
            for (let offset = 0; offset < length; offset++) {
                if (nums[firstStart + offset] !== nums[secondStart + offset]) {
                    return false;
                }
            }
            return true;
        }

        function recordWindow(start) {
            let groups = groupsByHash.get(hash);

            if (!groups) {
                groups = [];
                groupsByHash.set(hash, groups);
            }

            // Equal hashes can represent different subarrays.
            // Increase a count only after comparing the actual elements.
            for (const group of groups) {
                if (sameWindow(group.start, start)) {
                    group.count++;
                    return;
                }
            }

            groups.push({ start: start, count: 1 });
        }

        // Build the first window's hash from left to right.
        for (let i = 0; i < length; i++) {
            hash = (hash * BASE + nums[i]) % MOD;
        }
        recordWindow(0);

        // Remove the outgoing value, shift the weights, and add the new value.
        for (let start = 1; start + length <= n; start++) {
            const outgoing = (nums[start - 1] * highestPower) % MOD;
            hash = (hash - outgoing + MOD) % MOD;
            hash = (hash * BASE + nums[start + length - 1]) % MOD;
            recordWindow(start);
        }

        for (const groups of groupsByHash.values()) {
            for (const group of groups) {
                if (group.count === 1) return true;
            }
        }
        return false;
    }

    let lo = 1;
    let hi = n;
    let answer = n;

    while (lo <= hi) {
        const mid = Math.floor((lo + hi) / 2);

        if (hasUnique(mid)) {
            answer = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    return answer;
};

var smallestUniqueSubarray = function(nums) {
    // STEP 1: Generate every suffix.
    const suffixes = nums.map((_, i) => nums.slice(i));

    // STEP 2: Sort suffixes lexicographically.
    suffixes.sort((a, b) => {
        for (let i = 0; i < Math.min(a.length, b.length); i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }

        return a.length - b.length;
    });

    // STEP 3: Find the longest matching prefix
    // between two suffixes.
    function lcp(a, b) {
        if (!a || !b) return 0;

        let i = 0;

        while (
            i < a.length &&
            i < b.length &&
            a[i] === b[i]
        ) {
            i++;
        }

        return i;
    }

    // STEP 4: Find the shortest unique prefix
    // for every suffix.
    let best = nums.length;

    for (let i = 0; i < suffixes.length; i++) {
        const curr = suffixes[i];

        const prevLcp = lcp(curr, suffixes[i - 1]);
        const nextLcp = lcp(curr, suffixes[i + 1]);

        const needed = Math.max(prevLcp, nextLcp) + 1;

        // The suffix must contain enough elements.
        if (needed <= curr.length) {
            best = Math.min(best, needed);
        }
    }

    return best;
};

var smallestUniqueSubarraySuffixArray = function(nums) {
    const n = nums.length;
    if (n === 1) return 1;

    // STEP 1: Give equal numbers equal ranks.
    const sortedValues = [...nums].sort((a, b) => a - b);
    const valueRank = Object.create(null);
    let groups = 0;

    for (const num of sortedValues) {
        if (valueRank[num] === undefined) {
            valueRank[num] = groups;
            groups++;
        }
    }

    let rank = nums.map(num => valueRank[num]);
    let sa = Array.from({ length: n }, (_, i) => i);

    // Stable counting sort for one half of a rank pair.
    // A missing second half has rank -1, ordered before other ranks.
    function countSort(indices, offset) {
        const count = new Int32Array(groups + 1);

        for (const start of indices) {
            const key = start + offset < n ? rank[start + offset] + 1 : 0;
            count[key]++;
        }

        let position = 0;
        for (let key = 0; key < count.length; key++) {
            const size = count[key];
            count[key] = position;
            position += size;
        }

        const result = new Array(n);
        for (const start of indices) {
            const key = start + offset < n ? rank[start + offset] + 1 : 0;
            result[count[key]++] = start;
        }
        return result;
    }

    // STEP 2: Sort suffixes by doubling the compared prefix length.
    // First sort by the second half, then the first half.
    for (let gap = 1; gap < n; gap *= 2) {
        sa = countSort(sa, gap);
        sa = countSort(sa, 0);

        const nextRank = new Array(n);
        nextRank[sa[0]] = 0;
        let newGroups = 1;

        for (let i = 1; i < n; i++) {
            const prev = sa[i - 1];
            const curr = sa[i];
            const prevSecond = prev + gap < n ? rank[prev + gap] : -1;
            const currSecond = curr + gap < n ? rank[curr + gap] : -1;

            const different = rank[prev] !== rank[curr] || prevSecond !== currSecond;
            if (different) newGroups++;
            nextRank[curr] = newGroups - 1;
        }

        rank = nextRank;
        groups = newGroups;
        if (groups === n) break;
    }

    // STEP 3: Calculate LCP between neighboring sorted suffixes.
    // lcp[i] is the common prefix length of sa[i-1] and sa[i].
    const pos = new Array(n);
    for (let i = 0; i < n; i++) {
        pos[sa[i]] = i;
    }

    const lcp = new Array(n).fill(0);
    let common = 0;

    for (let start = 0; start < n; start++) {
        const i = pos[start];
        if (i === 0) {
            common = 0;
            continue;
        }

        const prevStart = sa[i - 1];
        while (start + common < n && prevStart + common < n && nums[start + common] === nums[prevStart + common]) {
            common++;
        }

        lcp[i] = common;
        if (common > 0) common--;
    }

    // STEP 4: The first unique prefix has length max(neighbor LCPs) + 1.
    let best = n;

    for (let i = 0; i < n; i++) {
        const prevLcp = lcp[i];
        const nextLcp = lcp[i + 1] ?? 0;
        const needed = Math.max(prevLcp, nextLcp) + 1;
        const available = n - sa[i];

        if (needed <= available) {
            best = Math.min(best, needed);
        }
    }

    return best;
};

